/** Oldest `retired_at` whose hold is still running: a hold ends exactly `ORG_SLUG_HOLD_DAYS` after the rename. */
function holdCutoff(): string {
  return toIsoTimestamp(new Date(Date.now() - ORG_SLUG_HOLD_DAYS * MS_PER_DAY));
}

/** Resolves a slug to a live workspace: by its current slug, else by a slug it retired within the hold. */
export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (row) return toOrganization(row);

  const held = getDb()
    .select({ org: organizations })
    .from(organizationSlugHolds)
    .innerJoin(organizations, eq(organizations.id, organizationSlugHolds.orgId))
    .where(
      and(
        eq(organizationSlugHolds.slug, slug),
        gt(organizationSlugHolds.retiredAt, holdCutoff()),
        isNull(organizations.archivedAt),
      ),
    )
    .get();
  return held ? toOrganization(held.org) : null;
}

/**
 * Whether `orgId` may take `slug` as its current slug: no other workspace
 * (live or deleted) has it as current, and none holds it retired.
 */
export async function isOrgSlugAvailable(
  slug: string,
  orgId: OrgId,
): Promise<boolean> {
  const current = getDb()
    .select({ id: organizations.id })
    .from(organizations)
    .where(eq(organizations.slug, slug))
    .get();
  if (current && current.id !== orgId) return false;

  const hold = getDb()
    .select({ orgId: organizationSlugHolds.orgId })
    .from(organizationSlugHolds)
    .where(
      and(
        eq(organizationSlugHolds.slug, slug),
        gt(organizationSlugHolds.retiredAt, holdCutoff()),
      ),
    )
    .get();
  return !hold || hold.orgId === orgId;
}

/**
 * Makes `slug` the workspace's current slug and retires the one it replaces,
 * atomically. Taking a slug the workspace itself retired ends that retirement.
 */
export async function renameOrgSlug(
  orgId: OrgId,
  slug: string,
): Promise<Organization> {
  return getDb().transaction((tx) => {
    const current = tx
      .select()
      .from(organizations)
      .where(eq(organizations.id, orgId))
      .get();
    if (!current) throw new Error(`Organization ${orgId} not found`);

    const stamp = toIsoTimestamp(new Date());

    tx.delete(organizationSlugHolds)
      .where(eq(organizationSlugHolds.slug, slug))
      .run();

    const row = tx
      .update(organizations)
      .set({ slug, updatedAt: stamp })
      .where(eq(organizations.id, orgId))
      .returning()
      .get();

    tx.delete(organizationSlugHolds)
      .where(eq(organizationSlugHolds.slug, current.slug))
      .run();
    tx.insert(organizationSlugHolds)
      .values({ slug: current.slug, orgId, retiredAt: stamp })
      .run();

    return toOrganization(row);
  });
}''')
